import subprocess,json,sys,os
EXE='/workspace/executable'
def query(src, rules=None, extra='', name='q.go', fmt='json', raw=False):
 path='/tmp/revive-probes/'+name
 open(path,'w').write(src)
 a=[EXE,'-formatter',fmt]
 if rules is not None:
  c=extra+'\n'+'\n'.join('[rule.'+r+']'+ ('\n'+v if v else '') for r,v in (rules.items() if isinstance(rules,dict) else [(r,'') for r in rules]))
