func (f *File) emptyBlock(){ast.Inspect(f.AST,func(n ast.Node)bool{emit:=func(b *ast.BlockStmt){if b!=nil&&len(b.List)==0&&!commentsInside(f,b){f.add(b,"this block is empty, you can remove it","logic",1)}};switch x:=n.(type){case *ast.IfStmt:emit(x.Body);if b,ok:=x.Else.(*ast.BlockStmt);ok{emit(b)};case *ast.ForStmt:emit(x.Body);case *ast.RangeStmt:if len(x.Body.List)==0&&!commentsInside(f,x.Body){f.add(x,"this block is empty, you can remove it","logic",.9)};case *ast.SwitchStmt:emit(x.Body);case *ast.TypeSwitchStmt:emit(x.Body);case *ast.BlockStmt:for _,s:=range x.List{if b,ok:=s.(*ast.BlockStmt);ok{emit(b)}}};return true})}
