func (f *File) apply(rule string){switch rule{
case "package-comments":f.packageComments()
case "exported":f.exportedRule()
case "var-naming":f.varNaming()
case "var-declaration":f.varDecl()
case "unused-parameter","unused-receiver":f.unused()
case "receiver-naming":f.receiverNaming()
case "redefines-builtin-id":f.redefines()
case "unexported-return":f.unexportedReturn()
case "error-naming":f.errorNaming()
case "error-return":f.errorReturn()
