}}
func (f *File) packageComments(){
 if strings.HasSuffix(f.Name,"_test.go"){return}
 if f.AST.Doc==nil{if f.First&&!f.Pkg.HasDoc{f.addRange(f.AST.Package,f.AST.Name.End(),"should have a package comment","comments",1,"")};return}
 if f.AST.Name.Name=="main"{return}
 text:=f.AST.Doc.Text();want:="Package "+f.AST.Name.Name+" "
 if !strings.HasPrefix(text,want)&&!strings.HasPrefix(text,"Package "+f.AST.Name.Name+"\n"){f.add(f.AST.Doc,fmt.Sprintf("package comment should be of the form %q","Package "+f.AST.Name.Name+" ..."),"comments",1)}
}
func startsDoc(doc *ast.CommentGroup,name string,article bool)bool{if doc==nil{return false};s:=doc.Text();if article{for _,p:=range []string{"A ","An ","The "}{s=strings.TrimPrefix(s,p)}};if s==name||strings.HasPrefix(s,name+" ")||strings.HasPrefix(s,name+"\n")||strings.HasPrefix(s,name+"'"){return true};return false}
func (f *File) exportedRule(){
 check:=func(node ast.Node,id string,what string,doc *ast.CommentGroup,article bool){if doc==nil{f.add(node,fmt.Sprintf("exported %s %s should have comment or be unexported",what,id),"comments",1)}else{dn:=id;if i:=strings.LastIndex(dn,".");i>=0{dn=dn[i+1:]};if !startsDoc(doc,dn,article){f.add(doc,fmt.Sprintf("comment on exported %s %s should be of the form %q",what,id,dn+" ..."),"comments",.8)}}}
