  if !exported(x.Name.Name){continue};if x.Recv==nil{if f.RC.has("disableChecksOnFunctions"){continue};check(x,x.Name.Name,"function",x.Doc,false);stutter(x.Name,"func")}else{if f.RC.has("disableChecksOnMethods"){continue};rn:=receiverType(x.Recv.List[0].Type);if !exported(rn)&&!f.RC.has("checkPrivateReceivers"){continue};if x.Name.Name=="String"||x.Name.Name=="Error"||x.Name.Name=="Read"||x.Name.Name=="Write"||x.Name.Name=="ServeHTTP"||x.Name.Name=="Unwrap"{continue};check(x,rn+"."+x.Name.Name,"method",x.Doc,false)}
