  if f.RC.has("checkPublicInterface"){if in,ok:=n.Type.(*ast.InterfaceType);ok{for _,field:=range in.Methods.List{for _,id:=range field.Names{if exported(id.Name){check(field,n.Name.Name+"."+id.Name,"method",field.Doc,false)}}}}}
