 }}}
 }
}
func (f *File) unused(){f.functions(func(ft *ast.FuncType,body *ast.BlockStmt,fd *ast.FuncDecl){if body==nil{return};if f.Rule=="unused-receiver"{if fd!=nil&&fd.Recv!=nil{for _,field:=range fd.Recv.List{for _,n:=range field.Names{if n.Name!="_"&&!hasName(body,n.Name){f.add(n,fmt.Sprintf("method receiver '%s' is not referenced in method's body, consider removing or renaming it as _",n.Name),"bad practice",1)}}}};return};if ft.Params==nil{return};for _,field:=range ft.Params.List{for _,n:=range field.Names{if n.Name=="_"{continue};opt:=f.RC.options();if boolean(opt["allowregex"]){continue};if pattern:=str(opt["allowregex"]);pattern!=""{if r,e:=regexp.Compile(pattern);e==nil&&r.MatchString(n.Name){continue}};if !hasName(body,n.Name){f.add(n,fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _",n.Name),"bad practice",1)}}}})}
