func cognitive(n ast.Node,depth int)int{count:=0;ast.Inspect(n,func(x ast.Node)bool{if x==nil{return true};switch s:=x.(type){case *ast.IfStmt:count+=1+depth;count+=cognitive(s.Cond,depth);count+=cognitive(s.Body,depth+1);if s.Else!=nil{count++;if _,ok:=s.Else.(*ast.IfStmt);ok{count+=cognitive(s.Else,depth)-1}else{count+=cognitive(s.Else,depth+1)}};return false;case *ast.ForStmt:count+=1+depth;count+=cognitive(s.Body,depth+1);return false;case *ast.RangeStmt:count+=1+depth;count+=cognitive(s.Body,depth+1);return false;case *ast.SwitchStmt:count+=1+depth;count+=cognitive(s.Body,depth+1);return false;case *ast.TypeSwitchStmt:count+=1+depth;count+=cognitive(s.Body,depth+1);return false;case *ast.SelectStmt:count+=1+depth;count+=cognitive(s.Body,depth+1);return false;case *ast.BinaryExpr:if s.Op==token.LAND||s.Op==token.LOR{count++};case *ast.BranchStmt:if s.Label!=nil{count++}};return true});return count}
func (f *File) importRules(rule string){seen:=map[string]bool{};for _,s:=range f.AST.Imports{path:=litString(s.Path);switch rule{case "imports-blocklist","imports-blacklist":for _,a:=range f.RC.Args{pattern:=str(a);r,e:=regexp.Compile(pattern);if e==nil&&r.MatchString(path){old:=f.Rule;f.Rule="imports-blocklist";f.add(s,"should not use the following blocklisted import: "+s.Path.Value,"imports",1);f.Rule=old;break}}
