 case "import-alias-naming":if s.Name!=nil&&s.Name.Name!="_"&&s.Name.Name!="."{pattern:="^[a-z][a-z0-9]{0,}$";if len(f.RC.Args)>0&&str(f.RC.Args[0])!=""{pattern=str(f.RC.Args[0])};if r,e:=regexp.Compile(pattern);e==nil&&!r.MatchString(s.Name.Name){f.add(s.Name,fmt.Sprintf("import name (%s) must match the regular expression: %s",s.Name.Name,pattern),"imports",1)}}
