 }}}
func (f *File) addConstant(){opts:=f.RC.options();allowed:=map[string]bool{};for _,key:=range []string{"allowints","allowfloats","allowstrs"}{for _,s:=range strings.Split(str(opts[key]),","){allowed[s]=true}};stringsCount:=map[string][]*ast.BasicLit{};ast.Inspect(f.AST,func(n ast.Node)bool{switch x:=n.(type){case *ast.GenDecl:return false;case *ast.BasicLit:if allowed[x.Value]||allowed[litString(x)]{return true};if x.Kind==token.INT||x.Kind==token.FLOAT||x.Kind==token.IMAG{f.add(x,fmt.Sprintf("avoid magic numbers like '%s', create a named constant for it",x.Value),"style",1)}else if x.Kind==token.STRING{stringsCount[x.Value]=append(stringsCount[x.Value],x)}};return true});max:=number(opts["maxlitcount"],2);for value,ls:=range stringsCount{if len(ls)>max{f.add(ls[0],fmt.Sprintf("string literal %s appears, at least, %d times, create a named constant for it",value,len(ls)),"style",1)}}}
func (f *File) importShadowing(){imports:=map[string]bool{};for _,i:=range f.AST.Imports{name:=filepath.Base(litString(i.Path));if i.Name!=nil{name=i.Name.Name};imports[name]=true};emit:=func(id *ast.Ident){if imports[id.Name]{f.add(id,fmt.Sprintf("The name '%s' shadows an import name",id.Name),"naming",1)}};ast.Inspect(f.AST,func(n ast.Node)bool{switch x:=n.(type){case *ast.AssignStmt:if x.Tok==token.DEFINE{for _,e:=range x.Lhs{if id,ok:=e.(*ast.Ident);ok{emit(id)}}};case *ast.ValueSpec:for _,id:=range x.Names{emit(id)};case *ast.FuncType:if x.Params!=nil{for _,field:=range x.Params.List{for _,id:=range field.Names{emit(id)}}}};return true})}
