func (f *File) identicalRules(rule string){visited:=map[*ast.IfStmt]bool{};ast.Inspect(f.AST,func(n ast.Node)bool{switch rule{case "identical-switch-branches","identical-switch-conditions":s,ok:=n.(*ast.SwitchStmt);if !ok{return true};seen:=map[string]ast.Node{};for _,b:=range s.Body.List{cl:=b.(*ast.CaseClause);if rule=="identical-switch-conditions"{for _,e:=range cl.List{key:=f.print(e);if first,ok:=seen[key];ok{f.add(e,fmt.Sprintf("duplicated case %s in switch",f.print(first)),"logic",1)};seen[key]=e}}else{parts:=[]string{};for _,st:=range cl.Body{parts=append(parts,f.print(st))};key:=strings.Join(parts,"\n");if first,ok:=seen[key];ok{f.add(s,fmt.Sprintf("\"switch\" with identical branches (lines %d and %d)",f.pos(first.Pos()).Line,f.pos(cl.Pos()).Line),"logic",1)}else{seen[key]=cl}}}
