func lintSnippet(t *testing.T, name, source, rule string, args ...any) []Failure {
 t.Helper()
 fs:=token.NewFileSet()
 tree,err:=parser.ParseFile(fs,name,source,parser.ParseComments)
 if err!=nil {t.Fatal(err)}
 rc:=&RuleConfig{Args:args}
 cfg:=&Config{Rules:map[string]*RuleConfig{rule:rc},Confidence:.8,Severity:"warning",Directives:map[string]string{}}
 pkg:=&Package{Name:tree.Name.Name,HasDoc:tree.Doc!=nil,Types:map[string]*ast.TypeSpec{},Functions:map[string]*ast.FuncDecl{}}
 for _,d:=range tree.Decls{switch x:=d.(type){case *ast.GenDecl:for _,s:=range x.Specs{if ts,ok:=s.(*ast.TypeSpec);ok{pkg.Types[ts.Name.Name]=ts}};case *ast.FuncDecl:pkg.Functions[x.Name.Name]=x}}
 f:=&File{Name:name,Src:source,AST:tree,Fset:fs,Config:cfg,Pkg:pkg,First:true,RC:rc,Rule:rule}
 f.directives();f.Rule=rule;f.apply(rule)
 var out []Failure
 for _,d:=range f.Failures{if d.Confidence>=cfg.Confidence{out=append(out,d)}}
 return out
}
