  {"get-return","package p\nfunc GetValue(){}\n","function 'GetValue' seems to be a getter",2,1},
  {"use-any","package p\nvar v interface{}\n","'interface{}' can be replaced by 'any'",2,7},
  {"unreachable-code","package p\nfunc f(){return;println(1)}\n","unreachable code after this statement",2,10},
  {"redefines-builtin-id","package p\nvar len=1\n","redefinition of the built-in function len",2,1},
 }
 for _,c:=range cases{t.Run(c.rule,func(t *testing.T){ds:=lintSnippet(t,"test.go",c.src,c.rule);if len(ds)!=1{t.Fatalf("expected one diagnostic, got %#v",ds)};d:=ds[0];if !strings.Contains(d.Failure,c.match){t.Errorf("message: %q",d.Failure)};if d.Position.Start.Line!=c.line||d.Position.Start.Column!=c.column{t.Errorf("position: %v; wanted %d:%d",d.Position.Start,c.line,c.column)}})}
}
func TestScopeResolution(t *testing.T){
 src:="package p\ntype T struct{x int}\nfunc f(x int){var a T;_=a.x}\nfunc g(x int){x=1}\nfunc h(x int){for x:=range []int{1}{_=x}}\n"
 ds:=lintSnippet(t,"scope.go",src,"unused-parameter")
 if len(ds)!=2||ds[0].Position.Start.Line!=3||ds[1].Position.Start.Line!=5{t.Fatalf("scope diagnostics: %#v",ds)}
}
func TestDirectivesAndGeneratedFiles(t *testing.T){
 src:="package p\n//revive:disable-next-line:exported\nfunc First(){}\nfunc Second(){}\n"
 ds:=lintSnippet(t,"directives.go",src,"exported")
 if len(ds)!=1||!strings.Contains(ds[0].Failure,"Second"){t.Fatalf("directives: %#v",ds)}
 if !generated("// Code generated by tests. DO NOT EDIT.\npackage p\n"){t.Fatal("generated header not recognized")}
 if generated("// Code generated by tests\npackage p\n"){t.Fatal("incomplete header marked generated")}
 if len(lintSnippet(t,"sample_test.go","package p\nfunc Helper(){}\n","exported"))!=0{t.Fatal("test declarations should be exempt from API comments")}
}
func TestConfigurationAndExclusions(t *testing.T){
 path:=filepath.Join(t.TempDir(),"config.toml")
 content:="severity=\"error\"\nconfidence=0.9\n[rule.line-length-limit]\narguments=[25]\n[rule.var-naming]\narguments=[[],[],[{skipPackageNameChecks=true}]]\n"
 if e:=os.WriteFile(path,[]byte(content),0600);e!=nil{t.Fatal(e)}
 c,e:=loadConfig(path);if e!=nil{t.Fatal(e)}
 if c.Confidence!=.9||c.severity("line-length-limit")!="error"||c.Rules["line-length-limit"].argInt(0,0)!=25{t.Fatalf("configuration: %#v",c)}
 if !boolean(c.Rules["var-naming"].options()["skippackagenamechecks"]){t.Fatal("nested option table was lost")}
 if ruleExcluded("/tmp/file.go",[]string{"*.go"}){t.Fatal("relative patterns should not match an absolute path")}
 if !ruleExcluded("/tmp/file.go",[]string{"**/*.go"}){t.Fatal("recursive exclusion failed")}
}
func TestLineLengthPosition(t *testing.T){
 ds:=lintSnippet(t,"length.go","package p\n\t// hello\n","line-length-limit",int64(10))
 if len(ds)!=1{t.Fatalf("length diagnostics: %#v",ds)}
 p:=ds[0].Position
 if p.Start.Offset!=0||p.Start.Line!=2||p.Start.Column!=0||p.End.Column!=12{t.Fatalf("length positions: %#v",p)}
}
EOF
cat > IMPLEMENTATION.md <<'EOF'
# Building and testing

Run `./compile.sh` to build `./executable`. The code uses Go's standard
library and does not require downloaded modules. A Go 1.21 or newer compiler
is sufficient.

Run `GOTOOLCHAIN=local go test ./src` for the regression tests.

## Organization

* `config.go`, `options.go`: TOML configuration and option validation.
* `main.go`: command-line handling, package/file selection, generated-file
  filtering, and exit status handling.
* `lint.go`: parsed-file state, source positions, and comment directives.
* `rules_*.go`: syntax-tree lint checks and their diagnostics.
* `format.go`: text, JSON, NDJSON, XML, SARIF, and tabular output.

The executable parses Go source with the standard Go parser. It uses the
installed Go toolchain to enumerate standard-library package names for the
package naming check. It does not invoke another linter.

Generated executables and test binaries are excluded by `.gitignore`.
EOF
